{"content":"/**
 * Pricing layer.
 *
 * Selling prices are resolved on the server from product cost + the markup
 * rules that apply to the current visitor (guest default, customer markup,
 * per-product override or negotiated price). The results are applied on top
 * of the static catalog so every screen shows account-correct pricing.
 */
import { createContext, useContext, useEffect, useState, type ReactNode } from "react";
import { useServerFn } from "@tanstack/react-start";
import { applyPriceOverrides, type PriceOverride } from "@/data/catalog";
import { getEffectivePrices } from "@/lib/pricing.functions";
import { supabase } from "@/integrations/supabase/client";

interface PricingValue {
  /** Bumps whenever prices change, so consumers re-render. */
  version: number;
  customerId: string | null;
  loading: boolean;
  refresh: () => void;
}

const PricingContext = createContext<PricingValue>({
  version: 0,
  customerId: null,
  loading: true,
  refresh: () => {},
});

export function PricingProvider({ children }: { children: ReactNode }) {
  const fetchPrices = useServerFn(getEffectivePrices);
  const [version, setVersion] = useState(0);
  const [customerId, setCustomerId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [nonce, setNonce] = useState(0);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    void (async () => {
      try {
        const result = await fetchPrices();
        if (cancelled) return;
        const map: Record<string, PriceOverride> = {};
        for (const p of result.prices) {
          map[p.slug] = {
            price: p.price,
            uom: p.uom,
            availability: p.availability,
            mfrPartNumber: p.mfrPartNumber,
            pickrelSku: p.pickrelSku,
          };
        }
        applyPriceOverrides(map);
        setCustomerId(result.customerId);
        setVersion((v) => v + 1);
      } catch (error) {
        console.error("Failed to load pricing", error);
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [fetchPrices, nonce]);

  useEffect(() => {
    const { data } = supabase.auth.onAuthStateChange((event) => {
      if (event === "SIGNED_IN" || event === "SIGNED_OUT" || event === "USER_UPDATED") {
        setNonce((n) => n + 1);
      }
    });
    return () => data.subscription.unsubscribe();
  }, []);

  return (
    <PricingContext.Provider value={{ version, customerId, loading, refresh: () => setNonce((n) => n + 1) }}>
      {children}
    </PricingContext.Provider>
  );
}

export function usePricing(): PricingValue {
  return useContext(PricingContext);
}
